package ktanesolver.module.modded.regular.orderedkeys;import static org.assertj.core.api.Assertions.assertThat;import java.util.*;import org.junit.jupiter.api.Test;import ktanesolver.entity.*;import ktanesolver.logic.*;import ktanesolver.module.modded.regular.orderedkeys.OrderedKeysInput.*;
class OrderedKeysSolverTest{@Test void decodesTableAndOrdersByRank(){List<Key> keys=new ArrayList<>();for(int p=0;p<6;p++){int label=0;for(int l=1;l<=6;l++)if(OrderedKeysSolver.rank(new Key(Color.RED,Color.RED,l),p)==p+1){label=l;break;}keys.add(new Key(Color.RED,Color.RED,label));}ModuleEntity m=new ModuleEntity();var out=(SolveSuccess<OrderedKeysOutput>)new OrderedKeysSolver().solve(new RoundEntity(),new BombEntity(),m,new OrderedKeysInput(1,keys));assertThat(out.output().ranks()).containsExactly(1,2,3,4,5,6);assertThat(out.output().pressOrder()).containsExactly(1,2,3,4,5,6);assertThat(out.output().twitchCommand()).isEqualTo("press 123456");assertThat(m.getState()).containsKey("orderedKeysStage1");}}
